# Generated from the reviewed ATA20 public-page source. No credentials or app data.
from pathlib import Path
import base64, gzip, hashlib, json, runpy, tempfile
root = Path.cwd()
server = root / 'server.py'
expected = '60c25c67785358cc9863c7aa1e16ea8e3c714e0d8d4310e433c30ceb7f458ec0'
original = server.read_bytes()
assert hashlib.sha256(original).hexdigest() == expected, 'Server changed; stop and review.'
files = json.loads(gzip.decompress(base64.b64decode('')))
for name, content in files.items():
    target = root / name
    assert not target.exists() or target.read_bytes() == base64.b64decode(content), 'Existing file differs: ' + name
backup = Path(tempfile.mkdtemp(prefix='ata20-before-20260918-')) / 'server.py'
backup.write_bytes(original)
for name, content in files.items():
    target = root / name
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_bytes(base64.b64decode(content))
runpy.run_path(str(root / 'integrate_fatinah.py'))['integrate'](server)
print('PUBLIC_SITE_INSTALLED', len(files), 'FILES')
print('SERVER_SHA256', hashlib.sha256(server.read_bytes()).hexdigest())
print('BACKUP', backup)
